/bin/bash -lc "node --input-type=module <<'NODE'
import { chromium } from '@playwright/test'

const browser = await chromium.launch({ headless: true })
for (const [label, expectedHeading, expectedProducts] of [
  ['Featured products', 'Featured products', ['Desk Lamp', 'Wool Blanket']],
  ['Products on sale', 'Products on sale', ['Canvas Tote', 'Travel Mug']],
]) {
  const page = await browser.newPage()
  const prefetchResponses = []
  page.on('response', async (response) => {
    if (response.url().includes('/catalog') && response.request().headers()['next-router-prefetch']) {
      prefetchResponses.push({ url: response.url(), body: await response.text() })
    }
  })
  await page.goto('http://127.0.0.1:3000/')
  await page.waitForTimeout(2500)
  await page.evaluate(() => {
    window.loadingSeen = false
    new MutationObserver(() => {
      if (document.body.textContent.includes('Loading category...')) window.loadingSeen = true
    }).observe(document.body, { subtree: true, childList: true, characterData: true })
  })
  const started = Date.now()
  await page.getByRole('link', { name: label }).click()
  await page.getByRole('heading', { name: expectedHeading, exact: true, level: 2 }).waitFor()
  const elapsed = Date.now() - started
  const productTexts = await page.locator('section li').allTextContents()
  console.log(JSON.stringify({
    label,
    url: page.url(),
    elapsed,
    loadingSeen: await page.evaluate(() => window.loadingSeen),
    productTexts,
    prefetchResponses: prefetchResponses.map(({ url, body }) => ({ url, hasHeading: body.includes(expectedHeading), hasProducts: expectedProducts.every(product => body.includes(product)) })),
  }))
  await page.close()
}
await browser.close()
NODE"

