/bin/bash -lc "node --input-type=module <<'NODE'
import { chromium } from '@playwright/test'
const browser = await chromium.launch({ headless: true })
const page = await browser.newPage()
const logs = []
const start = Date.now()
for (const event of ['request', 'response', 'requestfinished', 'requestfailed']) {
  page.on(event, (thing) => {
    const request = event === 'response' ? thing.request() : thing
    if ("'!request.url().includes('"'/catalog')) return
    logs.push({ t: Date.now() - start, event, url: request.url(), prefetch: request.headers()['next-router-prefetch'], segment: request.headers()['next-router-segment-prefetch'], status: event === 'response' ? thing.status() : undefined, failure: event === 'requestfailed' ? request.failure() : undefined })
  })
}
await page.goto('http://127.0.0.1:3000/')
await page.waitForTimeout(6000)
console.log('BEFORE', JSON.stringify(logs))
await page.getByRole('link', { name: 'Featured products' }).click()
await page.getByText('Desk Lamp').waitFor()
console.log('AFTER', JSON.stringify(logs))
await browser.close()
NODE"

